# Generated by Descant: acceptance tests.

# frozen_string_literal: true

# Delivery to the monolith's consumer fake (TimekeepingContract::FakeRelay)
# through the shared doubles. Replay, ignored, 403 and stale_generation answers
# come from the consumer fake, never from a script, because only the real fake
# can catch a bad idempotency key; the one scripted answer is the outage 503,
# which the consumer never gives.
#
# "Keep every distinct check: lost-mark replay, larger-batch resend counted ignored, outage then recovery,
# stale_generation then accepted, the 403 case, and equal positions from two sources."
RSpec.describe TimekeepingRelay::Relay, "delivery to the fake projection" do
  def outbox_row(position, **options)
    TimekeepingRelaySpec::MemoryOutboxSource.row(position, **options)
  end

  it "resends the same batch under the same key after a lost mark and leaves the projection unchanged" do
    endpoint, projection = TimekeepingRelaySpec::FakeRelayEndpoint.over_projection
    source = TimekeepingRelaySpec::MemoryOutboxSource.new([outbox_row(3, id: 77)])
    relay = described_class.new(source:, endpoint:)

    source.fail_next_mark!
    expect { relay.deliver(limit: 10) }.to raise_error(IOError)
    expect(source.lost_marks).to eq([[3]])
    expect(source.sent_positions).to be_empty
    projected = projection.projected_entry(77)
    expect(projected).to include("id" => 77)

    # "The relay marks a row sent only after a `200`, so delivery is at least once."
    expect(relay.deliver(limit: 10)).to eq(sent: 1, last_position: 3)
    expect(endpoint.posts.size).to eq(2)
    expect(endpoint.posts[1][:key]).to eq(endpoint.posts[0][:key])
    expect(endpoint.posts[1][:batch]).to eq(endpoint.posts[0][:batch])
    expect(endpoint.posts[1][:answer].status).to eq(200)
    expect(endpoint.posts[1][:answer].body).to eq(endpoint.posts[0][:answer].body)
    expect(projection.projected_entry(77)).to eq(projected)
    expect(source.sent_positions).to eq([3])
  end

  it "counts a row resent inside a larger batch after a lost mark as ignored" do
    endpoint, projection = TimekeepingRelaySpec::FakeRelayEndpoint.over_projection
    source = TimekeepingRelaySpec::MemoryOutboxSource.new([outbox_row(1, id: 10)])
    relay = described_class.new(source:, endpoint:)

    source.fail_next_mark!
    expect { relay.deliver(limit: 10) }.to raise_error(IOError)
    expect(source.lost_marks).to eq([[1]])
    expect(source.sent_positions).to be_empty

    source.add(outbox_row(2, id: 11))
    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 2)

    # The larger batch is a different body, so it carries a new key and the
    # consumer, not a replayed answer, counts row 1 as already applied.
    expect(endpoint.posts.size).to eq(2)
    expect(endpoint.posts[1][:key]).not_to eq(endpoint.posts[0][:key])
    expect(endpoint.posts[1][:answer].status).to eq(200)
    expect(endpoint.posts[1][:answer].body).to eq("applied" => 1, "ignored" => 1)
    expect(source.sent_positions).to contain_exactly(1, 2)
    expect(projection.projected_entry(10)).to include("id" => 10, "version" => 1)
    expect(projection.projected_entry(11)).to include("id" => 11, "version" => 1)
  end

  it "marks and projects nothing during an outage, then delivers the same batch under the same key" do
    endpoint, projection = TimekeepingRelaySpec::FakeRelayEndpoint.over_projection(
      answers: [TimekeepingRelay::Response.new(status: 503, body: {})]
    )
    source = TimekeepingRelaySpec::MemoryOutboxSource.new([outbox_row(1, id: 10), outbox_row(2, id: 11)])
    relay = described_class.new(source:, endpoint:)

    # "resends after an outage, and survives duplicates"
    expect(relay.deliver(limit: 10)).to eq(sent: 0, last_position: nil)
    expect(source.mark_calls).to be_empty
    expect(projection.projected_entry(10)).to be_nil

    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 2)
    expect(endpoint.posts.size).to eq(2)
    expect(endpoint.posts[1][:batch]).to eq(endpoint.posts[0][:batch])
    expect(endpoint.posts[1][:key]).to eq(endpoint.posts[0][:key])
    expect(source.sent_positions).to contain_exactly(1, 2)
    expect(projection.projected_entry(10)).to include("id" => 10)
    expect(projection.projected_entry(11)).to include("id" => 11)
  end

  it "marks nothing after the consumer's stale_generation refusal until the same batch is accepted" do
    endpoint, projection = TimekeepingRelaySpec::FakeRelayEndpoint.over_projection
    generation = TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION
    source = TimekeepingRelaySpec::MemoryOutboxSource.new(
      [outbox_row(5, id: 105, generation:), outbox_row(9, id: 109, generation:)]
    )
    relay = described_class.new(source:, endpoint:)

    projection.generation = generation + 1
    expect(relay.deliver(limit: 10)).to eq(sent: 0, last_position: nil)
    expect(endpoint.posts.size).to eq(1)
    expect(endpoint.posts[0][:answer].status).to eq(409)
    expect(endpoint.posts[0][:answer].body).to include("reason" => "stale_generation")
    expect(source.mark_calls).to be_empty
    expect(source.sent_positions).to be_empty
    expect(projection.projected_entry(105)).to be_nil

    projection.generation = generation
    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 9)
    expect(endpoint.posts[1][:batch]).to eq(endpoint.posts[0][:batch])
    expect(endpoint.posts[1][:key]).to eq(endpoint.posts[0][:key])
    expect(source.sent_positions).to contain_exactly(5, 9)
    expect(projection.projected_entry(109)).to include("id" => 109)
  end

  it "gets the consumer's 403 for a credential without deliver and marks or projects nothing" do
    endpoint, projection = TimekeepingRelaySpec::FakeRelayEndpoint.over_projection(name: "reporting", operations: ["read"])
    source = TimekeepingRelaySpec::MemoryOutboxSource.new([outbox_row(4), outbox_row(6)])

    result = described_class.new(source:, endpoint:).deliver(limit: 1)

    expect(result).to eq(sent: 0, last_position: nil)
    expect(endpoint.posts.size).to eq(1)
    expect(endpoint.posts[0][:answer].status).to eq(403)
    expect(endpoint.posts[0][:answer].delivered?(1)).to be(false)
    expect(source.mark_calls).to be_empty
    expect(source.sent_positions).to be_empty
    expect(projection.projected_entry(4)).to be_nil
  end

  it "projects both entries from two sources with equal positions" do
    endpoint, projection = TimekeepingRelaySpec::FakeRelayEndpoint.over_projection
    first = TimekeepingRelaySpec::MemoryOutboxSource.new([outbox_row(1, id: 301)])
    second = TimekeepingRelaySpec::MemoryOutboxSource.new([outbox_row(1, id: 302)])

    expect(described_class.new(source: first, endpoint:).deliver(limit: 10)).to eq(sent: 1, last_position: 1)
    expect(described_class.new(source: second, endpoint:).deliver(limit: 10)).to eq(sent: 1, last_position: 1)

    # Each application numbers its own outbox, so equal positions must not make
    # the consumer replay one batch's answer for the other.
    expect(endpoint.posts.size).to eq(2)
    expect(endpoint.posts[1][:key]).not_to eq(endpoint.posts[0][:key])
    expect(endpoint.posts.map { |post| post[:answer].body }).to all(eq("applied" => 1, "ignored" => 0))
    expect(first.sent_positions).to eq([1])
    expect(second.sent_positions).to eq([1])
    expect(projection.projected_entry(301)).to include("id" => 301)
    expect(projection.projected_entry(302)).to include("id" => 302)
  end
end
